question:
Lời gọi cuối cùng trả về gì?
`function isAnagram(a, b) {
  const count = {};
  for (const c of a) count[c] = (count[c] || 0) + 1;
  for (const c of b) {
    if (!count[c]) return false;
    count[c]--;
  }
  return true;
}
isAnagram('abc', 'ab');`

